-- =============================================================================
-- Migration 0052: K.4 Theorie B — Primitieven bij een kwadratische noemer
-- =============================================================================
-- Gegenereerd door scripts/k4b-content.ts — niet met de hand bewerken.
--
-- Het tweede theorieblok van K.4. De discriminant van de noemer bepaalt
-- de route: D < 0 geeft een logaritme en een arctangens, D = 0 een
-- logaritme en een breuk, D > 0 twee logaritmen.
--
-- Vijf clusters: de drie gevallen, bepaalde integralen, en vlakdelen.
--
-- Eigen oefenvragen, geen boekopgaven. Elke primitieve wordt nagerekend door
-- src/content/primitieven.test.ts (content/hoofdstuk-k/k4b.json).
--
-- Alleen toevoegen: geen DELETE, DROP of ALTER, en geen UPDATE op bestaande
-- vragen. De enige UPDATE zet theory_block_id op de topics van dit blok,
-- en alleen als die koppeling er nog niet staat. Twee keer draaien voegt
-- niets dubbel toe.
--
--   • 1 hoofdstuk, 3 topics, 5 clusters
--   • 40 vragen met elk 4 stappen (160 stappen)
-- =============================================================================

BEGIN;

-- 1. Hoofdstuk
INSERT INTO public.chapters (slug, title, book_part, order_index, site)
VALUES ('k', $ksql$K — Voortgezette integraalrekening$ksql$, 4, 12, 'integralen')
ON CONFLICT (slug) DO NOTHING;

-- 1b. Paragraaf en theorieblok
INSERT INTO public.paragraphs (chapter_id, site, slug, label, title, order_index)
SELECT c.id, 'integralen', 'k4', 'K.4', 'Breuksplitsen', 5
FROM public.chapters c
WHERE c.slug = 'k' AND c.site = 'integralen'
ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.theory_blocks (paragraph_id, site, slug, letter, title, order_index)
SELECT p.id, 'integralen', 'k4b', 'B', 'Primitieven bij een kwadratische noemer', 2
FROM public.paragraphs p
WHERE p.slug = 'k4' AND p.site = 'integralen'
ON CONFLICT (slug) DO NOTHING;

-- 2. Topics
INSERT INTO public.topics_new (slug, title, chapter_id, order_index, is_unlocked_by_default, site, category)
SELECT v.slug, v.title, (SELECT id FROM public.chapters WHERE slug = 'k' AND site = 'integralen'), v.order_index, true, 'integralen', v.category
FROM (VALUES
  ('k4b_primitiveren', $ksql$Breuken met een kwadratische noemer$ksql$, 30, 'primitiveren'),
  ('k4b_bepaald', $ksql$Bepaalde integralen met een kwadratische noemer$ksql$, 31, 'integralen'),
  ('k4b_toepassing', $ksql$Vlakdelen met een kwadratische noemer$ksql$, 32, 'toepassingen')
) AS v(slug, title, order_index, category)
ON CONFLICT (slug) DO NOTHING;

-- 3. Clusters
INSERT INTO public.topic_clusters_new (topic_id, slug, title, order_index, site)
SELECT t.id, v.slug, v.title, v.order_index, 'integralen'
FROM (VALUES
  ('k4b_primitiveren', 'k4b_negatief', $ksql$Discriminant kleiner dan nul$ksql$, 1),
  ('k4b_primitiveren', 'k4b_nul', $ksql$Discriminant nul$ksql$, 2),
  ('k4b_primitiveren', 'k4b_positief', $ksql$Discriminant groter dan nul$ksql$, 3),
  ('k4b_bepaald', 'k4b_bepaald', $ksql$Bepaalde integralen met een kwadratische noemer$ksql$, 1),
  ('k4b_toepassing', 'k4b_oppervlakte', $ksql$Oppervlakte, inhoud en de waarde van p$ksql$, 1)
) AS v(topic_slug, slug, title, order_index)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
ON CONFLICT (topic_id, slug) DO NOTHING;

-- 4. Vragen
