  ('k4b_primitiveren', 'k4b_nul', $ksql$Primitiveer: $f(x) = \dfrac{1}{(x - 3)^{2}}$$ksql$, $ksql$-1/(x - 3) + c$ksql$, $ksql$F(x) = -\dfrac{1}{x - 3} + c$ksql$, 1, 1, ARRAY[]::text[]),
  ('k4b_primitiveren', 'k4b_nul', $ksql$Primitiveer: $f(x) = \dfrac{2x - 6}{(x - 3)^{2}}$$ksql$, $ksql$2ln(abs(x - 3)) + c$ksql$, $ksql$F(x) = 2\ln|x - 3| + c$ksql$, 1, 2, ARRAY[]::text[]),
  ('k4b_primitiveren', 'k4b_nul', $ksql$Primitiveer: $f(x) = \dfrac{4x - 4}{(x - 1)^{2}}$$ksql$, $ksql$4ln(abs(x - 1)) + c$ksql$, $ksql$F(x) = 4\ln|x - 1| + c$ksql$, 1, 3, ARRAY[]::text[]),
