  ('k4b_primitiveren', 'k4b_nul', $ksql$Primitiveer: $f(x) = \dfrac{x^{2}}{(x - 1)^{2}}$$ksql$, $ksql$x + 2ln(abs(x - 1)) - 1/(x - 1) + c$ksql$, $ksql$F(x) = x + 2\ln|x - 1| - \dfrac{1}{x - 1} + c$ksql$, 3, 7, ARRAY[]::text[]),
