  ('k4b_primitiveren', 'k4b_positief', $ksql$Primitiveer: $f(x) = \dfrac{x^{2}}{x^{2} - 1}$$ksql$, $ksql$x + (1/2)ln(abs(x - 1)) - (1/2)ln(abs(x + 1)) + c$ksql$, $ksql$F(x) = x + \tfrac{1}{2}\ln|x - 1| - \tfrac{1}{2}\ln|x + 1| + c$ksql$, 3, 7, ARRAY[]::text[]),
  ('k4b_primitiveren', 'k4b_positief', $ksql$Primitiveer: $f(x) = \dfrac{x^{2} + 1}{(x - 1)(x - 2)}$$ksql$, $ksql$x - 2ln(abs(x - 1)) + 5ln(abs(x - 2)) + c$ksql$, $ksql$F(x) = x - 2\ln|x - 1| + 5\ln|x - 2| + c$ksql$, 3, 8, ARRAY[]::text[]),
  ('k4b_bepaald', 'k4b_bepaald', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \dfrac{2x + 2}{x^{2} + 2x + 2}\,\mathrm{d}x$$ksql$, $ksql$ln(5/2)$ksql$, $ksql$\ln\left(\tfrac{5}{2}\right)$ksql$, 1, 1, ARRAY[$ksql$ln(5) - ln(2)$ksql$, $ksql$ln(2,5)$ksql$]::text[]),
