  ('k4b_bepaald', 'k4b_bepaald', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \dfrac{2x}{(x + 1)^{2}}\,\mathrm{d}x$$ksql$, $ksql$2ln(2) - 1$ksql$, $ksql$2\ln(2) - 1$ksql$, 2, 4, ARRAY[]::text[]),
  ('k4b_bepaald', 'k4b_bepaald', $ksql$Bereken exact: $\displaystyle\int_{2}^{4} \dfrac{2}{(x - 1)(x + 1)}\,\mathrm{d}x$$ksql$, $ksql$ln(9/5)$ksql$, $ksql$\ln\left(\tfrac{9}{5}\right)$ksql$, 2, 5, ARRAY[$ksql$2ln(3) - ln(5)$ksql$, $ksql$ln(1,8)$ksql$]::text[]),
