  ('k4b_bepaald', 'k4b_bepaald', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \dfrac{4x}{x^{2} + 9}\,\mathrm{d}x$$ksql$, $ksql$2ln(10/9)$ksql$, $ksql$2\ln\left(\tfrac{10}{9}\right)$ksql$, 3, 8, ARRAY[$ksql$2ln(10) - 2ln(9)$ksql$, $ksql$ln(100/81)$ksql$]::text[]),
  ('k4b_toepassing', 'k4b_oppervlakte', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{1}{x^{2} + 1}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$(1/4)pi$ksql$, $ksql$\tfrac{1}{4}\pi$ksql$, 1, 1, ARRAY[$ksql$pi/4$ksql$, $ksql$1/4 pi$ksql$]::text[]),
